update ascent_game.circuit_lexicon l set links=(select jsonb_object_agg(w,e.reason) from jsonb_object_keys(l.links) w) from jsonb_to_recordset($notes$[{"clue":"luggage carousel","reason":"Arriving suitcases travel on a moving belt."},{"clue":"boarding pass","reason":"A passenger shows the pass at the gate to take an assigned seat."},{"clue":"windsock on a pole","reason":"A pilot reads the wind before landing."},{"clue":"departure board","reason":"The board lists flights, gates and delays."},{"clue":"tray of loose change","reason":"Travelers empty their pockets before the security check."},{"clue":"rings of saturn","reason":"Ice and rock orbit this gas giant in rings."},{"clue":"red giant","reason":"A star swells into a red giant late in its life."},{"clue":"spiral arms","reason":"Stars trace the spiral arms of galaxies like the Milky Way."},{"clue":"shadow on the moon","reason":"During a lunar eclipse, Earth casts its shadow on the Moon."},{"clue":"light years","reason":"A light year measures the distance light travels in a year."},{"clue":"folded egg whites","reason":"Whisking traps air in the whites, which can lift a sponge cake."},{"clue":"dough doubled in size","reason":"Yeast releases gas as bread dough proofs."},{"clue":"greased tin","reason":"Greasing the pan helps the cake release after baking."},{"clue":"floured worktop","reason":"Flour keeps dough from sticking as it is rolled."},{"clue":"wire cooling rack","reason":"Air passes beneath baked goods as they cool."},{"clue":"frame of capped cells","reason":"Bees seal the cells in a frame with wax."},{"clue":"white mesh hood","reason":"The veil protects the beekeeper’s face when the hive is opened."},{"clue":"jar of raw honey","reason":"Bees turn flower nectar into the honey that is harvested."},{"clue":"puffs of cool smoke","reason":"A beekeeper uses a smoker before inspecting the colony."},{"clue":"returning pollen gatherers","reason":"Worker bees carry pollen back to the hive."},{"clue":"guy lines","reason":"Lines tied to stakes keep a tent or tarp taut."},{"clue":"rolled sleeping pad","reason":"A sleeping pad insulates the sleeper from the ground."},{"clue":"ring of stones","reason":"Stones mark out the edge of a fire pit."},{"clue":"waterproof ground sheet","reason":"A ground sheet keeps damp soil off the tent floor."},{"clue":"folding camp stove","reason":"A portable stove lets campers cook over a controlled flame."},{"clue":"contour intervals","reason":"The gap in elevation between contour lines describes the slope."},{"clue":"north arrow","reason":"The arrow orients the map reader."},{"clue":"scale bar","reason":"The bar converts a length on paper to a distance on the ground."},{"clue":"dashed boundary","reason":"The legend explains which border a dashed line represents."},{"clue":"lines of latitude","reason":"Latitude measures position north or south of the equator."},{"clue":"forked king and rook","reason":"A knight can attack a king and rook in the same move."},{"clue":"back rank","reason":"A king trapped behind its pawns can be mated on its back rank."},{"clue":"fallen flag","reason":"The flag falls when a player runs out of time."},{"clue":"passed pawn","reason":"An unopposed pawn can advance toward promotion."},{"clue":"queenside castle","reason":"Castling moves the king to safety and brings the rook toward the center."},{"clue":"sawdust ring","reason":"Traditionally, sawdust covers the ring where the troupe performs."},{"clue":"suspended safety net","reason":"The net catches a trapeze artist who misses a grip."},{"clue":"painted smile","reason":"Makeup gives a clown a smile visible from across the ring."},{"clue":"three spinning clubs","reason":"A juggler keeps the clubs turning with timed throws."},{"clue":"striped big top","reason":"Poles support the canvas roof above the audience."},{"clue":"clipless pedals","reason":"A cleat under the shoe locks into the pedal."},{"clue":"flat inner tube","reason":"A punctured tube loses the air that supports the tire."},{"clue":"bunch sprint","reason":"The peloton accelerates together toward the finish line."},{"clue":"chain grease","reason":"Lubricant helps the chain run smoothly over the gears."},{"clue":"banked wooden track","reason":"Velodrome turns are banked for riders carrying speed."},{"clue":"tray of seedlings","reason":"Young plants start in trays before transplanting."},{"clue":"turned compost heap","reason":"Turning the heap aerates the material as it breaks down."},{"clue":"drip line","reason":"Drip irrigation delivers water close to the roots."},{"clue":"stakes and twine","reason":"Twine holds stems against stakes as the plants grow."},{"clue":"bed of mulch","reason":"Mulch helps soil retain moisture and suppresses weeds."},{"clue":"blue ice wall","reason":"Dense glacier ice can appear blue where a crevasse opens."},{"clue":"glacial flour","reason":"A glacier grinds rock into fine powder that meltwater carries away."},{"clue":"stranded boulder","reason":"Retreating ice can leave a boulder far from its source."},{"clue":"stream of meltwater","reason":"Ice melting in summer feeds a stream below the glacier."},{"clue":"u shaped valley","reason":"Moving ice erodes the floor and sides of a valley."},{"clue":"date due slip","reason":"A borrower checks the slip to see when the book must return."},{"clue":"call number","reason":"The shelf classification appears on the book spine."},{"clue":"quiet reading room","reason":"Readers consult books and reference materials in the reading room."},{"clue":"interlibrary loan","reason":"A library requests an item from another collection for a borrower."},{"clue":"bound back issues","reason":"Older issues of a periodical may be bound together for the archive."},{"clue":"raised baton","reason":"The conductor gives the ensemble its starting cue."},{"clue":"tuning note","reason":"The players tune to a shared pitch, usually sounded by the oboe."},{"clue":"sheet music","reason":"Players follow the notes on their music stands."},{"clue":"bowed strings","reason":"Violinists, violists and cellists draw bows across their strings."},{"clue":"kettle drums","reason":"The percussionist strikes the timpani with mallets."},{"clue":"plaster field jacket","reason":"Plaster protects a fossil while it is moved from an excavation."},{"clue":"petrified wood","reason":"Minerals preserve the structure of a plant long after it dies."},{"clue":"track in stone","reason":"A preserved footprint records the animal’s movement."},{"clue":"fossil bed","reason":"Fossils can accumulate in a layer of sedimentary rock."},{"clue":"curled ammonite shell","reason":"The coiled shell belonged to an ancient marine animal."},{"clue":"contact sheet","reason":"A photographer prints negatives together to inspect a roll."},{"clue":"slow shutter speed","reason":"A longer exposure records moving subjects as streaks."},{"clue":"wide open aperture","reason":"Opening the lens can leave only a shallow plane in focus."},{"clue":"roll of film","reason":"Exposed film is processed to reveal the images."},{"clue":"catchlight in the eye","reason":"Light reflected in the subject’s eye shows where the portrait light was placed."},{"clue":"foot ring","reason":"A potter trims a foot ring beneath a bowl."},{"clue":"glaze test tile","reason":"A small fired sample shows how a glaze looks after firing."},{"clue":"leather hard clay","reason":"Partly dried clay is firm enough to trim or attach a handle."},{"clue":"potters wheel","reason":"Spinning clay helps the potter shape an even bowl."},{"clue":"kiln shelf","reason":"A heat-resistant shelf supports vessels during firing."},{"clue":"points lever","reason":"The lever changes which track a train takes at a junction."},{"clue":"departure whistle","reason":"A whistle signals the train is ready to leave the platform."},{"clue":"wooden sleepers","reason":"Sleepers hold the rails in position above the ballast."},{"clue":"level crossing","reason":"Road traffic crosses the tracks here, often through a gate."},{"clue":"dining car","reason":"Passengers eat in this carriage during the journey."},{"clue":"coiled mooring line","reason":"The line secures the boat alongside the dock."},{"clue":"telltales on the jib","reason":"The small ribbons show airflow over the sail."},{"clue":"wake behind the stern","reason":"Water disturbed by the moving hull trails behind the stern."},{"clue":"spinnaker pole","reason":"The pole holds a corner of the sail out on a downwind course."},{"clue":"anchor chain","reason":"The chain connects the bow to an anchor on the seabed."},{"clue":"paper pattern","reason":"The tailor lays the pattern on fabric to guide the cut."},{"clue":"pinking shears","reason":"The toothed blades leave a zigzag edge to reduce fraying."},{"clue":"pressed seam","reason":"Pressing sets the stitches and flattens the seam allowance."},{"clue":"buttonhole stitch","reason":"Closely spaced stitches reinforce the cut edge of a buttonhole."},{"clue":"threaded bobbin","reason":"The bobbin supplies the lower thread for machine stitches."},{"clue":"curtain call","reason":"The cast returns to take a bow as the audience applauds."},{"clue":"dog eared script","reason":"The well-used script carries dialogue and stage directions for rehearsal."},{"clue":"spike tape","reason":"Tape marks where performers or pieces of scenery must stand."},{"clue":"empty prompt chair","reason":"A prompter follows the script to supply a missed line."},{"clue":"costume change","reason":"Actors change outfits backstage between appearances."},{"clue":"river of lava","reason":"Molten rock flows across the surface after an eruption."},{"clue":"column of ash","reason":"An eruption can loft ash into a plume above the crater."},{"clue":"steaming fissure","reason":"Hot gas and water vapor escape through the opening."},{"clue":"collapsed summit","reason":"A summit can collapse into a caldera when the magma chamber empties."},{"clue":"black glass fragments","reason":"Rapid cooling can turn lava into glassy obsidian."},{"clue":"warp threads","reason":"Warp strands run lengthwise through the loom under tension."},{"clue":"flying shuttle","reason":"The shuttle carries the weft between rows of warp threads."},{"clue":"woven border","reason":"The edge of a woven cloth may finish in a selvage or fringe."},{"clue":"raised heddles","reason":"Heddles lift warp strands to make a path for the shuttle."},{"clue":"tapestry on a loom","reason":"Colored yarn is woven into the design as the textile grows."}]$notes$::jsonb) as e(clue text,reason text) where l.edition=5 and l.clue=e.clue;